#!/usr/bin/env python3
"""Brogue grounding pass, as one file. Generated by tools/bundle_skill.py; do not edit.

Usage: python scripts/ground.py request.txt draft.txt

Uses the `claude` CLI if it is installed, else any OpenAI-compatible endpoint set
by BROGUE_BASE_URL, BROGUE_API_KEY and BROGUE_MODEL. Prints the grounded draft;
what was removed goes to stderr.
"""
from __future__ import annotations

from pathlib import Path

import json
import os
import shutil
import subprocess
import tempfile
import urllib.error
import urllib.request
from typing import Callable

LLM = Callable[[str, str], str]


class LLMError(RuntimeError):
    pass


class OpenAICompatible:
    def __init__(self, model: str | None = None, base_url: str | None = None,
                 api_key: str | None = None, temperature: float = 0.7, timeout: int = 120):
        self.model = model or os.environ.get("BROGUE_MODEL", "")
        self.base_url = (base_url or os.environ.get("BROGUE_BASE_URL")
                         or "https://api.openai.com/v1").rstrip("/")
        self.api_key = api_key or os.environ.get("BROGUE_API_KEY") or os.environ.get("OPENAI_API_KEY", "")
        self.temperature = temperature
        self.timeout = timeout
        if not self.model:
            raise LLMError("no model set: pass model=... or export BROGUE_MODEL")

    def __call__(self, system: str, user: str) -> str:
        body = json.dumps({
            "model": self.model,
            "temperature": self.temperature,
            "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
        }).encode()
        headers = {"Content-Type": "application/json"}
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"
        request = urllib.request.Request(f"{self.base_url}/chat/completions", data=body, headers=headers)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                payload = json.load(response)
        except urllib.error.HTTPError as err:
            raise LLMError(f"{err.code} from {self.base_url}: {err.read().decode(errors='replace')[:300]}") from err
        except urllib.error.URLError as err:
            raise LLMError(f"cannot reach {self.base_url}: {err.reason}") from err
        try:
            return payload["choices"][0]["message"]["content"].strip()
        except (KeyError, IndexError, TypeError, AttributeError) as err:
            raise LLMError(f"unexpected response shape: {str(payload)[:300]}") from err


class ClaudeCLI:
    """Use an installed Claude Code CLI as the model. No API key to manage.

    Every call is a fresh, isolated one-shot: no tools, no skills, no project
    instructions, an empty working directory. The system prompt passed in is
    the only system prompt, so the output reflects the prompt and nothing else.
    """

    def __init__(self, model: str = "haiku", timeout: int = 180, binary: str | None = None):
        self.model = model
        self.timeout = timeout
        self.binary = binary or shutil.which("claude") or ""
        if not self.binary:
            raise LLMError("claude CLI not found on PATH")
        self._cwd = tempfile.mkdtemp(prefix="brogue-")

    def __call__(self, system: str, user: str) -> str:
        command = [
            self.binary, "-p", "--model", self.model, "--system-prompt", system,
            "--tools", "", "--safe-mode", "--disable-slash-commands",
            "--strict-mcp-config", "--no-session-persistence",
        ]
        try:
            done = subprocess.run(command, input=user, capture_output=True, text=True,
                                  timeout=self.timeout, cwd=self._cwd)
        except subprocess.TimeoutExpired as err:
            raise LLMError(f"claude CLI timed out after {self.timeout}s") from err
        if done.returncode != 0:
            raise LLMError(f"claude CLI failed: {(done.stderr or done.stdout).strip()[:300]}")
        return done.stdout.strip()


def connect(provider: str = "auto", model: str | None = None, base_url: str | None = None) -> LLM:
    """Pick a model backend. 'auto' prefers an explicit API endpoint, then a local Claude CLI."""
    if provider == "auto":
        has_api = bool(base_url or os.environ.get("BROGUE_BASE_URL") or os.environ.get("BROGUE_API_KEY")
                       or os.environ.get("OPENAI_API_KEY"))
        provider = "openai" if has_api or not shutil.which("claude") else "claude-cli"
    if provider == "claude-cli":
        return ClaudeCLI(model or os.environ.get("BROGUE_MODEL") or "haiku")
    if provider == "openai":
        return OpenAICompatible(model=model, base_url=base_url)
    raise LLMError(f"unknown provider {provider!r}; use auto, openai or claude-cli")


import re
from dataclasses import dataclass, field

_URL = re.compile(r"https?://[^\s)>\]\"']+")
_EMAIL = re.compile(r"\b[\w.+-]+@[\w-]+\.[\w.-]+\b")
_NUMBER = re.compile(r"(?<![\w.])[$€£₹]?\d[\d,]*(?:\.\d+)?%?")
_QUOTED = re.compile(r"\"([^\"\n]{3,200})\"|“([^”\n]{3,200})”")
_CODE = re.compile(r"```.*?```|`[^`\n]+`", re.DOTALL)


def _norm_number(raw: str) -> str:
    return raw.replace(",", "").rstrip(".")


def facts(text: str) -> dict[str, set[str]]:
    code = {" ".join(m.group(0).split()) for m in _CODE.finditer(text)}
    body = _CODE.sub(" ", text)
    urls = {m.group(0).rstrip(".,;") for m in _URL.finditer(body)}
    emails = set(_EMAIL.findall(body))
    stripped = _EMAIL.sub(" ", _URL.sub(" ", body))
    return {
        "number": {_norm_number(n) for n in _NUMBER.findall(stripped)},
        "url": urls,
        "email": emails,
        "quote": {" ".join((a or b).split()) for a, b in _QUOTED.findall(stripped)},
        "code": code,
    }


@dataclass
class GuardReport:
    added: dict[str, list[str]] = field(default_factory=dict)
    dropped: dict[str, list[str]] = field(default_factory=dict)

    @property
    def ok(self) -> bool:
        return not self.added and not self.dropped

    def describe(self) -> str:
        if self.ok:
            return "facts preserved"
        parts = []
        for label, group in (("invented", self.added), ("dropped", self.dropped)):
            for kind, values in group.items():
                parts.append(f"{label} {kind}: {', '.join(values)}")
        return "; ".join(parts)


def compare(source: str, rewrite: str) -> GuardReport:
    before, after = facts(source), facts(rewrite)
    report = GuardReport()
    for kind in before:
        added = sorted(after[kind] - before[kind])
        dropped = sorted(before[kind] - after[kind])
        if added:
            report.added[kind] = added
        if dropped:
            report.dropped[kind] = dropped
    return report


import re
from dataclasses import dataclass, field


SYSTEM = """\
You check a draft against the only information its writer was given, and then you fix the draft.

Step 1. Read REQUEST. It is everything the writer knows about their own situation: their product, \
team, plans, what happened and why. Then read DRAFT one sentence at a time. List each statement in \
DRAFT about that situation which REQUEST neither states nor directly implies. Typical cases: a \
feature, benefit, material or instruction for use that nobody listed; a cause, reason or backstory; \
a claim about the state of things; a commitment made on the writer's behalf to do a specific thing or meet a specific time (an \
open invitation such as "tell me if this doesn't work", or an offer of something REQUEST says \
exists, is fine and stays); a \
name, number, date or duration; what happened to customers; what the rest of a document contains; \
an example told as if it happened.

Leave alone: anything worked out from REQUEST's own facts (a total, a difference, a percentage, the \
weekday of a given date, a consequence that follows by plain logic); explanations of what a fact \
means that are true in general and not about this writer, unless they carry a made-up figure; \
greetings, thanks and apologies; bracketed placeholders; an opinion or example clearly marked as one. \
Derived conclusions are often the most useful sentence in the draft. Cut only what had to be \
supplied from outside REQUEST.

Never list a statement that REQUEST supports, even loosely worded: every fact REQUEST supplies \
must survive. REQUEST may also give instructions ("offer to join next year", "ask them to reply"). \
Whatever it tells the writer to say, offer or ask for is supported, and stays.

Step 2. Write the draft again with every listed statement deleted, or cut back to what REQUEST \
says. Change nothing else: same voice, same order, same wording, same formatting. Add nothing. If a \
deletion leaves a sentence or paragraph broken, repair it with the fewest words. A shorter text is \
the expected result.

Reply in exactly this form:
<unsupported>
one statement per line, quoted from the draft, or the single word none
</unsupported>
<text>
the corrected draft
</text>"""


@dataclass
class Grounded:
    text: str
    removed: list[str] = field(default_factory=list)
    changed: bool = False
    warnings: list[str] = field(default_factory=list)

    def summary(self) -> str:
        head = f"grounded: {len(self.removed)} unsupported statement(s) removed" if self.changed \
            else "grounded: nothing to remove"
        return "\n".join([head, *[f"  - {r}" for r in self.removed], *[f"warning: {w}" for w in self.warnings]])


def _section(raw: str, tag: str) -> str | None:
    match = re.search(rf"<{tag}>\s*(.*?)\s*</{tag}>", raw, re.DOTALL)
    return match.group(1) if match else None


_WORDS = dict(zip("one two three four five six seven eight nine ten eleven twelve".split(), range(1, 13)))


def _digits(text: str) -> str:
    """Spell small numbers as digits so that "six years" and "6 years" compare equal."""
    return re.sub(r"\b(" + "|".join(_WORDS) + r")\b", lambda m: str(_WORDS[m.group(1).lower()]), text, flags=re.I)


def _problem(request: str, draft: str, text: str) -> str:
    """Why a correction cannot be accepted, or an empty string."""
    asked, had, after = (facts(_digits(t)) for t in (request, draft, text))
    added = sorted(x for kind in after for x in after[kind] - had[kind] - asked[kind])
    if added:
        return "the correction introduced " + ", ".join(added[:5])
    lost = sorted(x for kind in asked for x in (asked[kind] & had[kind]) - after[kind])
    if lost:
        return "the correction dropped " + ", ".join(lost[:5]) + ", which the request supplied"
    return ""


def ground(request: str, draft: str, llm: LLM, attempts: int = 2) -> Grounded:
    """Remove from `draft` whatever `request` does not support. One model call, a second if the first fails."""
    user, warnings = f"<request>\n{request}\n</request>\n\n<draft>\n{draft}\n</draft>", []
    for _ in range(attempts):
        raw = llm(SYSTEM, user if not warnings else
                  f"{user}\n\nYour previous correction was rejected: {warnings[-1]}. "
                  "Keep every fact the request supplies and add nothing.")
        listed, text = _section(raw, "unsupported"), _section(raw, "text")
        if listed is None or not text:
            warnings.append("the checker's reply could not be read")
            continue
        removed = [line.strip(" -\t\"'") for line in listed.splitlines() if line.strip(" -\t\"'")]
        if [r.lower() for r in removed] == ["none"] or not removed or text.strip() == draft.strip():
            return Grounded(draft)
        problem = _problem(request, draft, text)
        if not problem:
            return Grounded(text.strip(), removed, True)
        warnings.append(problem)
    return Grounded(draft, warnings=[*warnings, "draft returned unchanged"])


def main() -> int:
    import argparse
    import sys
    parser = argparse.ArgumentParser(description="Strike from a draft what the request never said.")
    parser.add_argument("request", help="file with what the writer was told (the brief, or the text being rewritten)")
    parser.add_argument("draft", help="file with the draft to check")
    parser.add_argument("--model", default=None, help="model id; default: haiku for the claude CLI")
    args = parser.parse_args()
    request = Path(args.request).read_text(encoding="utf-8")
    draft = Path(args.draft).read_text(encoding="utf-8")
    try:
        result = ground(request, draft, connect("auto", args.model))
    except LLMError as err:
        print(f"ground: no model available ({err}); check the draft by hand as SKILL.md describes", file=sys.stderr)
        return 3
    print(result.text)
    print(result.summary(), file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
